const questions = [
  { id:"seller", section:"מסמכים", title:"הרכב רשום על שם המוכר?", hint:"השוו בין תעודה מזהה לרישיון הרכב.", options:[["yes","כן, הכול תואם",0],["family","רשום על בן משפחה",10],["dealer","המוכר הוא סוחר",14],["unknown","לא בדקתי",22]] },
  { id:"license", section:"מסמכים", title:"פרטי הרכב תואמים לרישיון?", hint:"בדקו מספר רכב, דגם, שנה ומספר שלדה.", options:[["match","הכול תואם",0],["minor","לא בדקתי הכול",8],["mismatch","מצאתי פרט לא תואם",30],["unknown","לא יודע/ת איפה לבדוק",16]] },
  { id:"ownership", section:"מסמכים", title:"כמה בעלים היו לרכב?", hint:"המספר וסוג הבעלות מופיעים ברישיון.", options:[["first","יד ראשונה פרטית",0],["second","יד שנייה פרטית",4],["many","שלוש ידיים ומעלה",10],["lease","ליסינג, השכרה או חברה",14]] },
  { id:"liens", section:"מסמכים", title:"נבדקו שעבודים ועיקולים?", hint:"לא מעבירים כסף לפני שמוודאים שהרכב נקי מהגבלות.", options:[["clear","נבדק ואין הגבלות",0],["pending","עדיין לא בדקתי",16],["found","נמצאה הגבלה",40],["unknown","לא יודע/ת איך לבדוק",18]] },
  { id:"service", section:"מסמכים", title:"יש היסטוריית טיפולים?", hint:"בקשו חשבוניות או תיעוד ממוסך, לא רק הבטחה.", options:[["full","תיעוד מלא ורציף",0],["partial","תיעוד חלקי",7],["verbal","רק הבטחה בעל פה",16],["none","אין שום תיעוד",24]] },
  { id:"accident_history", section:"מסמכים", title:"מה ידוע על תאונות?", hint:"בקשו תשובה ברורה ומסמכים מתאימים.", options:[["none","ללא תאונות ויש תיעוד",0],["cosmetic","תיקוני צבע או פח קלים",6],["unclear","הייתה תאונה, ההיקף לא ברור",20],["chassis","נאמר שהייתה פגיעת שלדה",40]] },

  { id:"paint", section:"מרכב", title:"הצבע אחיד בכל הרכב?", hint:"הסתכלו באור יום וחפשו גוון שונה בין חלקים.", options:[["even","הצבע נראה אחיד",0],["minor","יש הבדל קטן",7],["obvious","יש הבדלי צבע ברורים",15],["unknown","לא הצלחתי לבדוק",8]] },
  { id:"gaps", section:"מרכב", title:"הרווחים בין הדלתות ישרים?", hint:"רווח עקום או דלת שלא נסגרת טוב עלולים להעיד על תיקון.", options:[["even","ישרים והדלתות נסגרות טוב",0],["minor","יש חוסר אחידות קטן",8],["bad","דלת או מכסה לא יושבים נכון",20],["unknown","לא יודע/ת לזהות",9]] },
  { id:"rust", section:"מרכב", title:"יש חלודה או ריקבון?", hint:"בדקו סביב הגלגלים, בתחתית הדלתות ובתא המטען.", options:[["none","לא ראיתי חלודה",0],["surface","מעט חלודה שטחית",6],["serious","חלודה עמוקה או מתפוררת",24],["unknown","לא הצלחתי לבדוק",8]] },
  { id:"glass", section:"מרכב", title:"השמשות והפנסים שלמים?", hint:"חפשו סדקים, שברים ואדים בתוך הפנסים.", options:[["good","הכול שלם",0],["small","יש פגם קטן",5],["bad","יש סדק או שבר משמעותי",12],["unknown","לא בדקתי",6]] },

  { id:"cold_start", section:"מנוע", title:"המנוע הותנע כשהוא קר?", hint:"בקשו מהמוכר לא לחמם את הרכב לפני ההגעה.", options:[["smooth","כן, הניע מיד ובשקט",0],["rough","היו רעידות או קושי",15],["warm","הרכב כבר היה חם",14],["unknown","לא יודע/ת אם היה קר",9]] },
  { id:"smoke", section:"מנוע", title:"יצא עשן חריג מהאגזוז?", hint:"עשן סמיך שנמשך אחרי ההתנעה הוא סימן לבדיקה.", options:[["none","לא ראיתי עשן חריג",0],["brief","מעט עשן שנעלם",6],["ongoing","עשן סמיך או מתמשך",30],["unknown","לא הצלחתי לראות",8]] },
  { id:"engine_noise", section:"מנוע", title:"שמעתם רעש חריג מהמנוע?", hint:"הקשיבו לנקישות, שריקות או רעש מתכתי.", options:[["quiet","המנוע נשמע יציב",0],["minor","יש רעש קל ולא ברור",10],["loud","יש רעש חזק או מתכתי",28],["unknown","לא יודע/ת להבחין",9]] },
  { id:"leaks", section:"מנוע", title:"יש טיפות או כתמים מתחת לרכב?", hint:"הסתכלו על הקרקע ומתחת לתא המנוע.", options:[["dry","יבש ונקי",0],["sweat","יש רטיבות קלה",7],["drops","יש טיפות או כתם",22],["unknown","לא הצלחתי לבדוק",9]] },
  { id:"fluids", section:"מנוע", title:"השמן ונוזל הקירור נראים תקינים?", hint:"בודקים רק כשהמנוע קר. לא פותחים מיכל קירור חם.", options:[["good","המפלס והצבע נראים תקינים",0],["low","חסר מעט נוזל",8],["bad","חסר הרבה או נראה חריג",26],["unknown","לא יודע/ת לבדוק",10]] },

  { id:"dashboard", section:"חשמל", title:"נורות האזהרה כבו לאחר ההתנעה?", hint:"נורת מנוע, שמן, כרית אוויר או ABS צריכה להיכבות.", options:[["clear","כולן כבו",0],["one","נורה אחת נשארה דולקת",24],["many","כמה נורות נשארו דולקות",34],["unknown","לא שמתי לב",10]] },
  { id:"electric", section:"חשמל", title:"המזגן והמערכות החשמליות עובדים?", hint:"נסו מזגן, חלונות, נעילה, אורות ומסך.", options:[["all","הכול עובד",0],["minor","יש תקלה קטנה",6],["several","כמה דברים לא עובדים",16],["unknown","לא בדקתי הכול",7]] },
  { id:"belts", section:"חשמל", title:"החגורות והמושבים תקינים?", hint:"משכו כל חגורה ובדקו שהיא ננעלת וחוזרת.", options:[["good","הכול תקין",0],["minor","יש בלאי קל",5],["bad","חגורה או מושב לא תקינים",22],["unknown","לא בדקתי",7]] },
  { id:"odor", section:"חשמל", title:"יש ריח חריג בתוך הרכב?", hint:"ריח עובש, דלק או שרוף דורש בירור.", options:[["none","אין ריח חריג",0],["musty","יש ריח קל של לחות",7],["strong","יש ריח דלק, שרוף או עובש חזק",24],["unknown","לא בטוח/ה",6]] },

  { id:"tires", section:"בלמים", title:"הצמיגים נראים שחוקים או סדוקים?", hint:"עברו סביב הרכב ובדקו את כל ארבעת הצמיגים.", options:[["good","נראים אחידים ותקינים",0],["worn","יש שחיקה קלה",7],["bad","יש סדקים או שחיקה חזקה",20],["unknown","לא יודע/ת לזהות",8]] },
  { id:"tire_age", section:"בלמים", title:"גיל הצמיגים נבדק?", hint:"ארבע הספרות על הצמיג מציינות שבוע ושנת ייצור.", options:[["new","עד ארבע שנים",0],["old","מעל ארבע שנים",9],["mixed","הצמיגים בגילים שונים",10],["unknown","לא בדקתי",7]] },
  { id:"brakes", section:"בלמים", title:"איך הרכב בלם בנסיעה?", hint:"בלמו בעדינות במקום בטוח והקשיבו לרעשים.", options:[["good","בלם ישר ובשקט",0],["noise","היה רעש או רעד קל",12],["unsafe","הבלימה חלשה או הרכב סטה",34],["unknown","לא ביצעתי בדיקה",12]] },

  { id:"straight", section:"נסיעה", title:"הרכב נוסע ישר?", hint:"בכביש ישר שימו לב אם הוא מושך לצד.", options:[["straight","נוסע ישר",0],["slight","מושך מעט לצד",10],["strong","מושך חזק או רועד",24],["unknown","לא הצלחתי לבדוק",9]] },
  { id:"steering", section:"נסיעה", title:"ההגה מרגיש יציב ושקט?", hint:"סובבו בעדינות וחפשו רעידות, חופש או רעש.", options:[["good","יציב ושקט",0],["minor","יש תחושה או רעש קל",9],["bad","יש חופש, רעד או רעש חזק",24],["unknown","לא יודע/ת להבחין",8]] },
  { id:"gearbox", section:"נסיעה", title:"ההילוכים עוברים בצורה חלקה?", hint:"שימו לב למכה, השהיה או קפיצה בהאצה.", options:[["smooth","עוברים חלק",0],["minor","הרגשתי מכה קלה",12],["bad","יש מכות, החלקה או השהיה",30],["unknown","לא הצלחתי לבדוק",10]] },
  { id:"suspension", section:"נסיעה", title:"יש רעשים בכביש משובש?", hint:"עברו לאט על שיבוש קטן והקשיבו לנקישות.", options:[["quiet","אין רעש חריג",0],["minor","יש רעש קל",8],["loud","יש נקישות או קפיצות חזקות",22],["unknown","לא בדקתי",8]] },

  { id:"pressure", section:"עסקה", title:"המוכר לוחץ לסגור מהר?", hint:"לחץ להעביר מקדמה לפני בדיקה הוא דגל אדום.", options:[["calm","לא, נותן זמן לבדוק",0],["some","יש מעט לחץ",10],["strong","לוחץ להעביר כסף עכשיו",30],["unknown","לא בטוח/ה",7]] },
  { id:"inspection", section:"עסקה", title:"המוכר מסכים לבדיקה במכון שתבחרו?", hint:"אתם בוחרים את המכון, לא המוכר.", options:[["yes","כן, בלי הסתייגות",0],["conditions","מסכים רק למכון מסוים",16],["no","לא מסכים לבדיקה",40],["unknown","עוד לא שאלתי",12]] },
] as const;

function riskCopy(score:number) {
  if (score <= 18) return { verdict:"שווה להתקדם לבדיקה", label:"סיכון נמוך", color:"good", text:"לא עלו כרגע סימנים חריגים, אבל לפני קנייה ממשיכים לבדיקה מקצועית מלאה." };
  if (score <= 42) return { verdict:"מתקדמים בזהירות", label:"סיכון בינוני", color:"warn", text:"יש כמה נקודות שדורשות אימות ותמחור. לא סוגרים לפני בדיקה וקבלת תשובות ברורות." };
  if (score <= 66) return { verdict:"רק עם מומחה ותנאים חזקים", label:"סיכון גבוה", color:"danger", text:"הצטברו דגלים אדומים משמעותיים. אם ממשיכים, רק במחיר שמגלם את הסיכון ולאחר בדיקה קפדנית." };
  return { verdict:"דוד אומר: לוותר", label:"סיכון חריג", color:"danger", text:"יותר מדי סימני אזהרה. יש מספיק רכבים בשוק. לא צריך להתאהב דווקא בחתול שבשק." };
}

export default function Home() {
  const [started,setStarted] = useState(false);
  const [step,setStep] = useState(0);
  const [answers,setAnswers] = useState<Answers>({});
  const [car,setCar] = useState({make:"",model:"",year:"",km:"",price:"",listPrice:""});
  const [detailsSubmitted,setDetailsSubmitted] = useState(false);
  const [done,setDone] = useState(false);
  const [showExit,setShowExit] = useState(false);
  const rawRisk = useMemo(() => questions.reduce((sum,q) => {
    const picked = q.options.find(o=>o[0]===answers[q.id]); return sum + (picked ? Number(picked[2]) : 0);
  },0),[answers]);
  const maxRisk = useMemo(() => questions.reduce((sum,q) => sum + Math.max(...q.options.map(o=>Number(o[2]))),0),[]);
  const score = Math.max(0,100-Math.round((rawRisk/maxRisk)*100));
  const result = riskCopy(100-score);
  const flags = questions.flatMap(q => { const o=q.options.find(x=>x[0]===answers[q.id]); return o && Number(o[2])>=14 ? [o[1]] : []; });
  const toNumber = (value:string) => Number(value.replace(/[^0-9]/g,"")) || 0;
  const askingPrice = toNumber(car.price);
  const currentListPrice = toNumber(car.listPrice);
  const hasListPrice = car.listPrice !== "unknown" && currentListPrice > 0;
  const negotiationBase = hasListPrice ? Math.min(askingPrice,currentListPrice) : askingPrice;
  const negotiationDiscount = score >= 82 ? .02 : score >= 65 ? .05 : score >= 45 ? .09 : .14;
  const negotiationPrice = Math.max(0,Math.round((negotiationBase*(1-negotiationDiscount))/1000)*1000);
  const formatPrice = (value:number) => new Intl.NumberFormat("he-IL").format(value);
  const choose=(id:string,value:string)=>{ setAnswers(a=>({...a,[id]:value})); setTimeout(()=>{ if(step<questions.length-1) setStep(s=>s+1); else setDone(true); },180); };
  const handleReport = async () => {
    const reportText = [
      "דוח בדיקה ראשוני – המומחה של דוד",
      `${car.make} ${car.model} · ${car.year} · ${car.km} ק״מ`,
      `ציון: ${score} מתוך 100`,
      `פסק דין: ${result.verdict}`,
      flags.length ? `דגלים לבדיקה: ${flags.join(" · ")}` : "לא סומנו דגלים אדומים משמעותיים",
      `מחיר מבוקש: ₪${car.price}`,
      `מחירון עדכני: ${hasListPrice ? `₪${car.listPrice}` : "לא נבדק"}`,
      `יעד למשא ומתן: ₪${formatPrice(negotiationPrice)}`,
    ].join("\n");

    if (typeof navigator !== "undefined" && navigator.share) {
      try {
        await navigator.share({
          title: "דוח בדיקת רכב – המומחה של דוד",
          text: reportText,
        });
        return;
      } catch (error) {
        if (error instanceof DOMException && error.name === "AbortError") return;
      }
    }

    window.print();
  };

  if(!started) return <main className="landing" dir="rtl">
    <header className="topbar"><div className="brand"><span className="brandmark" role="img" aria-label="רכב">🚘</span><div><b>המומחה של דוד</b><small>לא קונים חתול בשק</small></div></div><span className="tag">בדיקה חכמה לרכב יד שנייה</span></header>
    <section className="hero">
      <div className="heroCopy">
        <h1><span>הרכב נראה מציאה</span><em>בואו נבדוק מה הוא מסתיר.</em></h1>
        <p><span>בדיקה חכמה וקפדנית לפני קניית רכב יד שנייה.</span><span>בתוך כחמש דקות תקבלו ציון, דגלים אדומים ופסק דין ברור.</span></p>
      </div>
      <div className="inspectionVisual" aria-label="תרשים אזורי בדיקה ברכב">
        <img className="beetleIllustration" src="data:image/webp;base64," alt="חיפושית אספנות כתומה מאוירת"/>
      </div>
      <div className="heroBottom">
        <span className="eyebrow">לפני שמעבירים מקדמה</span>
        <div className="heroActions"><button className="primary" onClick={()=>setStarted(true)}>מתחילים בדיקה <span>←</span></button><span className="time">כחמש דקות ⏱</span></div>
      </div>
    </section>
    <section className="trust"><div><b>01</b><span>מכניסים פרטים</span></div><i>←</i><div><b>02</b><span>בודקים כמו מקצוענים</span></div><i>←</i><div><b>03</b><span>מקבלים פסק דין</span></div></section>
    <footer><b>חשוב לדעת:</b> הכלי מסייע בסינון ובהכנה ואינו מחליף בדיקה במכון מורשה, בדיקת מסמכים או ייעוץ מקצועי.</footer>
  </main>;

  if(!detailsSubmitted) return <main className="app" dir="rtl"><div className="appTop"><button className="logoBtn" aria-label="חזרה למסך הפתיחה" onClick={()=>setStarted(false)}>🚘</button><div className="progress"><span>פרטי הרכב</span><div><i style={{width:"8%"}}/></div></div></div><section className="formCard"><span className="stepNum">שלב ראשון</span><h2>איזה רכב מצאתם?</h2><p>נתחיל בפרטים היבשים. אחר כך נצלול למה שבאמת חשוב.</p><div className="fields"><label>יצרן<input value={car.make} onChange={e=>setCar({...car,make:e.target.value})} placeholder="לדוגמה: טויוטה"/></label><label>דגם<input value={car.model} onChange={e=>setCar({...car,model:e.target.value})} placeholder="לדוגמה: קורולה"/></label><label>שנת ייצור<input inputMode="numeric" value={car.year} onChange={e=>setCar({...car,year:e.target.value})} placeholder="2020"/></label><label>קילומטראז׳<input inputMode="numeric" value={car.km} onChange={e=>setCar({...car,km:e.target.value})} placeholder="85,000"/></label><label>מחיר מבוקש ₪<input inputMode="numeric" value={car.price} onChange={e=>setCar({...car,price:e.target.value})} placeholder="72,000"/></label><div className="listPriceRow"><label>מחירון עדכני ₪<input inputMode="numeric" value={car.listPrice==="unknown"?"":car.listPrice} onChange={e=>setCar({...car,listPrice:e.target.value})} placeholder={car.listPrice==="unknown"?"לא נבדק":"לדוגמה: 68,000"}/></label><button type="button" className={car.listPrice==="unknown"?"unknownPrice active":"unknownPrice"} onClick={()=>setCar({...car,listPrice:car.listPrice==="unknown"?"":"unknown"})}>{car.listPrice==="unknown"?"✓ לא בדקתי":"לא בדקתי"}</button></div></div><button className="primary full" disabled={!Object.values(car).every(Boolean)} onClick={()=>{setDetailsSubmitted(true);setStep(0)}}>ממשיכים לבדיקה ←</button></section></main>;

  if(done) return <main className="resultPage" dir="rtl"><header className="resultHead"><div className="brand"><span className="brandmark" role="img" aria-label="רכב">🚘</span><div><b>המומחה של דוד</b><small>דוח בדיקה ראשוני</small></div></div><button onClick={handleReport}>שיתוף / שמירת הדוח</button></header><section className="resultHero"><span className={`risk ${result.color}`}>{result.label}</span><h1 className={`verdictStamp ${result.color}`}>{result.verdict}</h1><p>{car.make} {car.model} · {car.year} · {car.km} ק״מ</p><div className={`scoreRing ${result.color}`}><strong>{score}</strong><span>מתוך 100</span></div><p className="resultText">{result.text}</p></section><section className="reportGrid"><article><h3>🚩 דגלים שדורשים תשובה</h3>{flags.length ? <ul>{flags.map((f,i)=><li key={i}>{f}</li>)}</ul> : <p className="empty">לא סומנו דגלים אדומים משמעותיים.</p>}</article><article><h3>💬 מה לשאול את המוכר עכשיו</h3><ul><li>אפשר לקבל תיעוד טיפולים וחשבוניות?</li><li>האם הרכב עבר תאונה או תיקון משמעותי?</li><li>האם קיימים שעבודים, עיקולים או התחייבויות?</li><li>האם תסכים לבדיקה במכון שאני בוחר/ת?</li></ul></article><article><h3>🔧 מה לבקש מהמכון לבדוק</h3><ul><li>שלדה, קצות שלדה וסימני תיקון</li><li>מנוע, מערכת קירור, נזילות ולחצי מנוע</li><li>גיר, מתלים, בלמים, היגוי וצמיגים</li><li>סריקת מחשב והיסטוריית תקלות</li></ul></article><article className="price negotiation"><h3>משא ומתן</h3><dl><div><dt>מחיר מבוקש</dt><dd>₪{car.price}</dd></div><div><dt>מחירון עדכני</dt><dd>{hasListPrice ? `₪${car.listPrice}` : "לא נבדק"}</dd></div><div className="targetPrice"><dt>אפשר לשאוף להגיע ל</dt><dd>₪{formatPrice(negotiationPrice)}</dd></div></dl><p>מחיר היעד מחושב לפי המחיר המבוקש, המחירון והליקויים שסומנו. הוא מושפע גם ממצב השוק ומהבדיקה המקצועית.</p><small>זהו כלי עזר למשא ומתן ולא הערכת שמאי.</small></article></section><div className="bottomActions"><a className="primary" href="tel:0527922238" aria-label="חיוג לדוד להתייעצות טלפונית" style={{textDecoration:"none",textAlign:"center",minWidth:180}}>📞 להתייעצות עם דוד</a><button className="primary" onClick={()=>{setDone(false);setStep(0)}}>חזרה לתשובות</button><button className="secondary" onClick={()=>{setCar({make:"",model:"",year:"",km:"",price:"",listPrice:""});setAnswers({});setDone(false);setStep(0);setDetailsSubmitted(false)}}>בדיקת רכב נוסף</button></div><footer><b>לתשומת לב:</b> זהו דוח סינון ראשוני המבוסס על המידע שמסרתם. הוא אינו מהווה אחריות למצב הרכב ואינו מחליף בדיקה מקצועית ומסמכית.</footer></main>;

  const q=questions[step];
  return <main className="app" dir="rtl"><div className="appTop"><button className="logoBtn" aria-label="פתיחת אפשרויות יציאה" onClick={()=>setShowExit(true)}>🚘</button><div className="progress"><span>שאלה {step+1} מתוך {questions.length}</span><div><i style={{width:`${(step+1)/questions.length*100}%`}}/></div></div><span className="carPill">{car.make} {car.model} · {car.year}</span></div><section className="questionCard"><span className="stepNum">{q.section} · {String(step+1).padStart(2,"0")}</span><h2>{q.title}</h2><p>{q.hint}</p><div className="options">{q.options.map(o=><button key={o[0]} className={answers[q.id]===o[0]?"selected":""} onClick={()=>choose(q.id,o[0])}><b className="optionText">{o[1]}</b><span className="choiceMark" aria-hidden="true"/><i aria-hidden="true">←</i></button>)}</div>{q.id==="service"&&<p className="expertFootnote">לא ראית חשבונית? מבחינתנו זה לא קרה.</p>}<div className="inspectionProgress" aria-label="התקדמות הבדיקה מימין לשמאל">
        <div className="stageTrack"><i style={{width:`${(step+1)/questions.length*100}%`}}/></div>
        <div className="stageLabels seven"><span>עסקה</span><span>נסיעה</span><span>בלמים</span><span>חשמל</span><span>מנוע</span><span>מרכב</span><span>מסמכים</span></div>
      </div><div className="nav"><button disabled={step===0} onClick={()=>setStep(s=>s-1)}>→ הקודם</button><button onClick={()=>setShowExit(true)}>שמירה ויציאה</button></div></section>{showExit&&<div className="modal"><div><h3>לעצור את הבדיקה?</h3><p>התשובות נשמרות כל עוד החלון פתוח.</p><button className="primary" onClick={()=>setShowExit(false)}>להמשיך לבדוק</button><button className="secondary" onClick={()=>setStarted(false)}>חזרה להתחלה</button></div></div>}</main>;
}
